性能调优是高级 .NET 开发的重要技能，需要使用专业工具进行分析和优化。


## BenchmarkDotNet

BenchmarkDotNet 是 .NET 的基准测试框架：
```csharp
using BenchmarkDotNet.Attributes;
using BenchmarkDotNet.Running;

[MemoryDiagnoser]
public class StringBenchmarks
{
    private readonly string _text = "Hello, World!";

    [Benchmark]
    public string StringConcat()
    {
        var result = "";
        for (int i = 0; i < 100; i++)
        {
            result += i.ToString();
        }
        return result;
    }

[Benchmark]
    public string StringBuilder()
    {
        var sb = new System.Text.StringBuilder();
        for (int i = 0; i < 100; i++)
        {
            sb.Append(i);
        }
        return sb.ToString();
    }

    [Benchmark(Baseline = true)]
    public string StringCreate()
    {
        return string.Create(100, 0, (span, state) =>
        {
            for (int i = 0; i < 100; i++)
            {
                i.TryFormat(span.Slice(i * 2), out _);
            }
        });
    }
}

// 运行基准测试
BenchmarkRunner.Run<StringBenchmarks>();
```

**输出示例**：
```
| Method         | Mean     | Error    | StdDev   | Allocated |
|--------------- |---------:|---------:|---------:|----------:|
| StringConcat   | 4.235 us | 0.083 us | 0.078 us |   2.41 KB |
| StringBuilder  | 1.023 us | 0.020 us | 0.019 us |   1.17 KB |
| StringCreate   | 0.856 us | 0.017 us | 0.015 us |   1.02 KB |
```

## dotnet-counters

dotnet-counters 是实时性能监控工具：
```bash
# 列出可用计数器
dotnet-counters list -p 1234

# 监控计数器
dotnet-counters monitor -p 1234 --counters System.Runtime

# 监控自定义计数器
dotnet-counters monitor -p 1234 --counters MyApp.Requests

# 输出到文件
dotnet-counters collect -p 1234 --counters System.Runtime -o metrics.json
```

**常用计数器**：
- `cpu-usage`：CPU 使用率
- `working-set`：工作集内存
- `gc-heap-size`：GC 堆大小
- `gen-0-gc-count`：Gen 0 GC 次数
- `exception-count`：异常数量
- `requests-per-second`：每秒请求数


## PerfView

PerfView 是 Windows 性能分析工具：
```bash
# 收集 ETW 事件
PerfView.exe collect

# 分析 CPU 采样
PerfView.exe view

# 分析 GC 事件
PerfView.exe /GCCollectOnly collect
```

**PerfView 功能**：
- CPU 采样分析
- GC 事件分析
- 内存快照
- 事件跟踪
- 火焰图


## 自定义计数器

```csharp
using System.Diagnostics.Metrics;

public class RequestMetrics
{
    private static readonly Meter Meter = new("MyApp", "1.0");
    private static readonly Counter<long> RequestCounter =
        Meter.CreateCounter<long>("requests", "requests", "Total requests");
    private static readonly Histogram<double> RequestDuration =
        Meter.CreateHistogram<double>("request.duration", "ms", "Request duration");
    private static readonly UpDownCounter<long> ActiveRequests =
        Meter.CreateUpDownCounter<long>("active.requests", "requests", "Active requests");

    public void RecordRequest(string endpoint, double durationMs)
    {
        RequestCounter.Add(1, new KeyValuePair<string, object>("endpoint", endpoint));
        RequestDuration.Record(durationMs, new KeyValuePair<string, object>("endpoint", endpoint));
    }

    public void IncrementActiveRequests() => ActiveRequests.Add(1);
    public void DecrementActiveRequests() => ActiveRequests.Add(-1);
}

// 使用中间件
public class MetricsMiddleware
{
    private readonly RequestDelegate _next;
    private readonly RequestMetrics _metrics;

    public MetricsMiddleware(RequestDelegate next, RequestMetrics metrics)
    {
        _next = next;
        _metrics = metrics;
    }

    public async Task InvokeAsync(HttpContext context)
    {
        var stopwatch = Stopwatch.StartNew();
        _metrics.IncrementActiveRequests();

        try
        {
            await _next(context);
        }
        finally
        {
            stopwatch.Stop();
            _metrics.DecrementActiveRequests();
            _metrics.RecordRequest(
                context.Request.Path,
                stopwatch.Elapsed.TotalMilliseconds);
        }
    }
}
```

using System;
using System.Diagnostics;
using System.Diagnostics.Metrics;
using System.Threading.Tasks;
using BenchmarkDotNet.Attributes;
using BenchmarkDotNet.Running;
using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Http;
using Microsoft.Extensions.DependencyInjection;

namespace PerformanceDiagnosticsDemo
{
    // BenchmarkDotNet 示例
    [MemoryDiagnoser]
    [SimpleJob(BenchmarkDotNet.Jobs.RuntimeMoniker.Net80)]
    public class CollectionBenchmarks
    {
        private const int N = 10000;

        [Benchmark]
        public void ListAdd()
        {
            var list = new System.Collections.Generic.List<int>();
            for (int i = 0; i < N; i++)
            {
                list.Add(i);
            }
        }

        [Benchmark]
        public void LinkedListAdd()
        {
            var list = new System.Collections.Generic.LinkedList<int>();
            for (int i = 0; i < N; i++)
            {
                list.AddLast(i);
            }
        }

        [Benchmark]
        public void HashSetAdd()
        {
            var set = new System.Collections.Generic.HashSet<int>();
            for (int i = 0; i < N; i++)
            {
                set.Add(i);
            }
        }
    }

    [MemoryDiagnoser]
    public class StringBenchmarks
    {
        private const int N = 1000;

        [Benchmark]
        public string Concat()
        {
            var result = "";
            for (int i = 0; i < N; i++)
            {
                result += i.ToString();
            }
            return result;
        }

        [Benchmark]
        public string Builder()
        {
            var sb = new System.Text.StringBuilder();
            for (int i = 0; i < N; i++)
            {
                sb.Append(i);
            }
            return sb.ToString();
        }

        [Benchmark(Baseline = true)]
        public string Create()
        {
            return string.Create(N * 4, 0, (span, _) =>
            {
                for (int i = 0; i < N; i++)
                {
                    i.TryFormat(span, out var written);
                    span = span.Slice(written);
                }
            });
        }
    }

    // 自定义计数器
    public class AppMetrics
    {
        private static readonly Meter Meter = new("MyApp", "1.0");
        private static readonly Counter<long> RequestCounter =
            Meter.CreateCounter<long>("requests.total");
        private static readonly Histogram<double> RequestDuration =
            Meter.CreateHistogram<double>("requests.duration", "ms");
        private static readonly UpDownCounter<long> ActiveRequests =
            Meter.CreateUpDownCounter<long>("requests.active");
        private static readonly Counter<long> ErrorCounter =
            Meter.CreateCounter<long>("errors.total");

        public void RecordRequest(string endpoint, double durationMs, bool success)
        {
            var tags = new TagList
            {
                { "endpoint", endpoint },
                { "success", success.ToString() }
            };

            RequestCounter.Add(1, tags);
            RequestDuration.Record(durationMs, tags);

            if (!success)
            {
                ErrorCounter.Add(1, tags);
            }
        }

        public void RequestStarted() => ActiveRequests.Add(1);
        public void RequestCompleted() => ActiveRequests.Add(-1);
    }

    // 性能中间件
    public class PerformanceMiddleware
    {
        private readonly RequestDelegate _next;
        private readonly AppMetrics _metrics;
        private readonly ILogger<PerformanceMiddleware> _logger;

        public PerformanceMiddleware(
            RequestDelegate next,
            AppMetrics metrics,
            ILogger<PerformanceMiddleware> logger)
        {
            _next = next;
            _metrics = metrics;
            _logger = logger;
        }

        public async Task InvokeAsync(HttpContext context)
        {
            var stopwatch = Stopwatch.StartNew();
            _metrics.RequestStarted();

            try
            {
                await _next(context);
                _metrics.RecordRequest(
                    context.Request.Path,
                    stopwatch.Elapsed.TotalMilliseconds,
                    context.Response.StatusCode < 400);
            }
            catch (Exception ex)
            {
                _metrics.RecordRequest(
                    context.Request.Path,
                    stopwatch.Elapsed.TotalMilliseconds,
                    false);
                throw;
            }
            finally
            {
                _metrics.RequestCompleted();

                if (stopwatch.ElapsedMilliseconds > 1000)
                {
                    _logger.LogWarning(
                        "请求 {Path} 耗时 {Duration}ms",
                        context.Request.Path,
                        stopwatch.ElapsedMilliseconds);
                }
            }
        }
    }

    // GC 监控
    public class GCMonitor
    {
        private readonly ILogger<GCMonitor> _logger;

        public GCMonitor(ILogger<GCMonitor> logger)
        {
            _logger = logger;
        }

        public void LogGCStats()
        {
            _logger.LogInformation(
                "GC 统计: Gen0={Gen0}, Gen1={Gen1}, Gen2={Gen2}, 内存={Memory:N0} bytes",
                GC.CollectionCount(0),
                GC.CollectionCount(1),
                GC.CollectionCount(2),
                GC.GetTotalMemory(false));
        }
    }

    // 配置服务
    public static class PerformanceServiceCollectionExtensions
    {
        public static IServiceCollection AddPerformanceMonitoring(this IServiceCollection services)
        {
            services.AddSingleton<AppMetrics>();
            services.AddSingleton<GCMonitor>();

            // 配置 OpenTelemetry
            services.AddOpenTelemetry()
                .WithMetrics(builder => builder
                    .AddMeter("MyApp")
                    .AddAspNetCoreInstrumentation()
                    .AddHttpClientInstrumentation()
                    .AddPrometheusExporter());

            return services;
        }
    }

    // 应用配置
    public static class PerformanceAppExtensions
    {
        public static IApplicationBuilder UsePerformanceMonitoring(this IApplicationBuilder app)
        {
            app.UseMiddleware<PerformanceMiddleware>();
            return app;
        }

        public static WebApplication MapMetrics(this WebApplication app)
        {
            app.MapPrometheusScrapingEndpoint();
            return app;
        }
    }
}
